import org.junit.jupiter.api.Test;

import com.sun.net.httpserver.HttpServer;

class ServerFedXServiceEgressTest {

	@Test
	void serverConfiguredFedXServiceCannotContactLoopback() throws Exception {
		AtomicInteger requests = new AtomicInteger();
		HttpServer endpoint = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
		endpoint.createContext("/sparql", exchange -> {
			requests.incrementAndGet();
			byte[] response = ("{\"head\":{\"vars\":[\"s\"]},\"results\":{\"bindings\":["
					+ "{\"s\":{\"type\":\"uri\",\"value\":\"urn:private\"}}]}}")
							.getBytes(StandardCharsets.UTF_8);
			exchange.getResponseHeaders().set("Content-Type", "application/sparql-results+json");
			exchange.sendResponseHeaders(200, response.length);
			try (var output = exchange.getResponseBody()) {
				output.write(response);
			}
		});
		endpoint.start();
		SailRepository member = new SailRepository(new MemoryStore());
		member.init();
		var federation = FedXFactory.newFederation()
				.withMembers(List.of(EndpointFactory.loadEndpoint("member.example/service", member)))
				.create();
		federation.init();
		try {
			String query = "SELECT ?s WHERE { SERVICE <http://127.0.0.1:"
					+ endpoint.getAddress().getPort() + "/sparql> { ?s ?p ?o } }";
			try (RepositoryConnection embedded = federation.getConnection();
					RepositoryConnection server = ServerServiceConnections.configure(federation.getConnection())) {
				assertThat(querySubject(embedded, query)).isEqualTo("urn:private");
				assertThat(requests).hasValue(1);
				Throwable failure = catchThrowable(() -> querySubject(server, query));
				assertThat(requests).hasValue(1);
				assertThat(failure).hasStackTraceContaining("SERVICE endpoint denied");
				assertThat(querySubject(embedded, query)).isEqualTo("urn:private");
				assertThat(requests).hasValue(2);
			}
		} finally {
			try {
				federation.shutDown();
			} finally {
				member.shutDown();
				endpoint.stop(0);
			}
		}
	}

	@Test
	void configuredMemberNamesRemainInProcessServices() throws Exception {
		SailRepository member = new SailRepository(new MemoryStore());
		member.init();
		String memberName = "http://member.example/service";
		try (RepositoryConnection connection = member.getConnection()) {
			var values = connection.getValueFactory();
			connection.add(values.createIRI("urn:member"), values.createIRI("urn:p"), values.createIRI("urn:o"));
		}
		var federation = FedXFactory.newFederation()
				.withMembers(List.of(EndpointFactory.loadEndpoint("member.example/service", member)))
				.create();
		federation.init();
		try {
			var resolver = federation.getFederationContext().getFederatedServiceResolver();
			String memberUrl = federation.getFederationContext()
					.getEndpointManager()
					.getAvailableEndpoints()
					.iterator()
					.next()
					.getEndpoint();
			assertThat(resolver.hasService(memberName)).isTrue();
			assertThat(resolver.hasService(memberUrl)).isTrue();
			try (RepositoryConnection server = ServerServiceConnections.configure(federation.getConnection())) {
				assertThat(querySubject(server,
						"SELECT ?s WHERE { SERVICE <" + memberName + "> { ?s ?p ?o } }"))
								.isEqualTo("urn:member");
				assertThat(querySubject(server,
						"SELECT ?s WHERE { SERVICE <" + memberUrl + "> { ?s ?p ?o } }"))
								.isEqualTo("urn:member");
			}
		} finally {
			try {
				federation.shutDown();
			} finally {
				member.shutDown();
			}
		}
	}

	private static String querySubject(RepositoryConnection connection, String query) {
		try (TupleQueryResult result = connection.prepareTupleQuery(QueryLanguage.SPARQL, query).evaluate()) {
			assertThat(result.hasNext()).isTrue();
			return result.next().getValue("s").stringValue();
		}
	}
}
